WITH customer_returns AS ( SELECT c.c_customer_id, c.c_first_name, c.c_last_name, hd.hd_income_band_sk, SUM(sr.sr_return_amt_inc_tax) AS total_return_amount, COUNT(*) AS return_cnt, AVG(sr.sr_return_amt_inc_tax) AS avg_return_amount FROM store_returns sr JOIN customer c ON sr.sr_customer_sk = c.c_customer_sk JOIN household_demographics hd ON c.c_current_hdemo_sk = hd.hd_demo_sk JOIN date_dim d ON sr.sr_returned_date_sk = d.d_date_sk WHERE d.d_year = 2022 GROUP BY c.c_customer_id, c.c_first_name, c.c_last_name, hd.hd_income_band_sk ) SELECT c_customer_id, c_first_name, c_last_name, hd_income_band_sk, total_return_amount, return_cnt, avg_return_amount, RANK() OVER (ORDER BY total_return_amount DESC) AS revenue_rank, CASE WHEN total_return_amount > 5000 THEN 'High' WHEN total_return_amount > 2000 THEN 'Medium' ELSE 'Low' END AS return_category FROM customer_returns ORDER BY revenue_rank LIMIT 20
